from collections import deque
def f(g):
    R=len(g);C=len(g[0]);seen=[[False]*C for _ in range(R)];res=[row[:] for row in g];comps=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==0 and not seen[r][c]:
                q=deque([(r,c)]);seen[r][c]=True;cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<R and 0<=y<C and g[x][y]==0 and not seen[x][y]:
                            seen[x][y]=True;q.append((x,y))
                comps.append(cells)
    comps.sort(key=len)
    for r,c in comps[0]: res[r][c]=7
    for r,c in comps[-1]: res[r][c]=8
